"""Triplet margin loss (ATen-compatible) in Triton for the enflame S60 target.

Semantics (ATen):
    d_p(x, y) = norm(x - y + eps, p, dim=-1)      # eps added elementwise
    dist_pos = d_p(anchor, positive)
    dist_neg = d_p(anchor, negative)              # swap: min(., d_p(pos, neg))
    loss     = clamp_min(margin + dist_pos - dist_neg, 0)
    reduction: 0 -> loss (shape S[:-1]), 1 -> mean, 2 -> sum (0-dim)

Accumulation is fp32 (fp64 when the promoted dtype is fp64), no intermediate
rounding to the input dtype, so the result tracks the high-precision
reference used by the accuracy tests.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

_MAX_LEAD = 4
_GROUPS = [f"g{k}{s}" for k in range(_MAX_LEAD) for s in ("s", "a", "p", "n")]

_ROWS_NOS = [
    "R",
    "C",
    "margin",
    "eps",
    "pp",
    "scale",
    "RPP",
    "mode",
    "swap",
] + _GROUPS
_COLS_NOS = ["R", "C", "pp", "chunk", "Gc", "mode"] + _GROUPS
_COMB_NOS = ["R", "Gc", "margin", "pp", "scale", "mode", "swap"]
_RED_NOS = ["n", "scale"]

_RED_BLOCK = 2048
_COMB_BLOCK = 2048


@triton.jit
def _new_acc(BLOCK_C: tl.constexpr, ACC64: tl.constexpr, MODE: tl.constexpr):
    if ACC64:
        acc = tl.zeros([BLOCK_C], tl.float64)
    else:
        if MODE == 4:
            acc = tl.full([BLOCK_C], float("inf"), tl.float32)
        else:
            acc = tl.zeros([BLOCK_C], tl.float32)
    return acc


@triton.jit
def _new_one(ACC64: tl.constexpr):
    if ACC64:
        acc = tl.zeros([1], tl.float64)
    else:
        acc = tl.zeros([1], tl.float32)
    return acc


@triton.jit
def _stats_sum(
    a_base,
    p_base,
    n_base,
    c_start,
    c_end,
    C,
    eps,
    mode,
    BLOCK_C: tl.constexpr,
    ACC64: tl.constexpr,
):
    """Sum-type accumulation: modes 2 (square), 1 (abs), 0 (count)."""
    acc_ap = _new_acc(BLOCK_C, ACC64, 0)
    acc_an = _new_acc(BLOCK_C, ACC64, 0)
    acc_pn = _new_acc(BLOCK_C, ACC64, 0)
    dt = acc_ap.dtype
    cols = tl.arange(0, BLOCK_C)
    for c0 in range(c_start, c_end, BLOCK_C):
        cc = c0 + cols
        m = cc < C
        mm = m.to(dt)
        av = tl.load(a_base + cc, mask=m, other=0.0).to(dt)
        pv = tl.load(p_base + cc, mask=m, other=0.0).to(dt)
        nv = tl.load(n_base + cc, mask=m, other=0.0).to(dt)
        d_ap = (av - pv + eps) * mm
        d_an = (av - nv + eps) * mm
        d_pn = (pv - nv + eps) * mm
        acc_ap += tl.where(
            mode == 2,
            d_ap * d_ap,
            tl.where(mode == 1, tl.abs(d_ap), (d_ap != 0.0).to(dt)),
        )
        acc_an += tl.where(
            mode == 2,
            d_an * d_an,
            tl.where(mode == 1, tl.abs(d_an), (d_an != 0.0).to(dt)),
        )
        acc_pn += tl.where(
            mode == 2,
            d_pn * d_pn,
            tl.where(mode == 1, tl.abs(d_pn), (d_pn != 0.0).to(dt)),
        )
    return acc_ap, acc_an, acc_pn


@triton.jit
def _stats_pow(
    a_base,
    p_base,
    n_base,
    c_start,
    c_end,
    C,
    eps,
    pp,
    BLOCK_C: tl.constexpr,
):
    """General p: |d|^p via exp2(p * log2(|d|))."""
    acc_ap = tl.zeros([BLOCK_C], tl.float32)
    acc_an = tl.zeros([BLOCK_C], tl.float32)
    acc_pn = tl.zeros([BLOCK_C], tl.float32)
    zero = tl.zeros([BLOCK_C], tl.float32)
    cols = tl.arange(0, BLOCK_C)
    for c0 in range(c_start, c_end, BLOCK_C):
        cc = c0 + cols
        m = cc < C
        av = tl.load(a_base + cc, mask=m, other=0.0).to(tl.float32)
        pv = tl.load(p_base + cc, mask=m, other=0.0).to(tl.float32)
        nv = tl.load(n_base + cc, mask=m, other=0.0).to(tl.float32)
        d_ap = av - pv + eps
        d_an = av - nv + eps
        d_pn = pv - nv + eps
        acc_ap += tl.where(m, tl.exp2(pp * tl.log2(tl.abs(d_ap))), zero)
        acc_an += tl.where(m, tl.exp2(pp * tl.log2(tl.abs(d_an))), zero)
        acc_pn += tl.where(m, tl.exp2(pp * tl.log2(tl.abs(d_pn))), zero)
    return acc_ap, acc_an, acc_pn


@triton.jit
def _stats_ext(
    a_base,
    p_base,
    n_base,
    c_start,
    c_end,
    C,
    eps,
    MODE: tl.constexpr,
    BLOCK_C: tl.constexpr,
):
    """Extremal norms: MODE 3 = max |d|, MODE 4 = min |d|."""
    acc_ap = _new_acc(BLOCK_C, False, MODE)
    acc_an = _new_acc(BLOCK_C, False, MODE)
    acc_pn = _new_acc(BLOCK_C, False, MODE)
    cols = tl.arange(0, BLOCK_C)
    for c0 in range(c_start, c_end, BLOCK_C):
        cc = c0 + cols
        m = cc < C
        av = tl.load(a_base + cc, mask=m, other=0.0).to(tl.float32)
        pv = tl.load(p_base + cc, mask=m, other=0.0).to(tl.float32)
        nv = tl.load(n_base + cc, mask=m, other=0.0).to(tl.float32)
        a_ap = tl.abs(av - pv + eps)
        a_an = tl.abs(av - nv + eps)
        a_pn = tl.abs(pv - nv + eps)
        if MODE == 4:
            acc_ap = tl.minimum(acc_ap, tl.where(m, a_ap, float("inf")))
            acc_an = tl.minimum(acc_an, tl.where(m, a_an, float("inf")))
            acc_pn = tl.minimum(acc_pn, tl.where(m, a_pn, float("inf")))
        else:
            acc_ap = tl.maximum(acc_ap, a_ap)
            acc_an = tl.maximum(acc_an, a_an)
            acc_pn = tl.maximum(acc_pn, a_pn)
    return acc_ap, acc_an, acc_pn


@triton.jit
def _row_parts(
    a_base,
    p_base,
    n_base,
    c_start,
    c_end,
    C,
    eps,
    mode,
    pp,
    BLOCK_C: tl.constexpr,
    ACC64: tl.constexpr,
):
    """Per-row chunk partials (sum, or extremum for modes 3/4)."""
    if ACC64:
        acc_ap, acc_an, acc_pn = _stats_sum(
            a_base, p_base, n_base, c_start, c_end, C, eps, mode, BLOCK_C, ACC64
        )
    else:
        if mode == 5:
            acc_ap, acc_an, acc_pn = _stats_pow(
                a_base, p_base, n_base, c_start, c_end, C, eps, pp, BLOCK_C
            )
        elif mode == 3:
            acc_ap, acc_an, acc_pn = _stats_ext(
                a_base, p_base, n_base, c_start, c_end, C, eps, 3, BLOCK_C
            )
        elif mode == 4:
            acc_ap, acc_an, acc_pn = _stats_ext(
                a_base, p_base, n_base, c_start, c_end, C, eps, 4, BLOCK_C
            )
        else:
            acc_ap, acc_an, acc_pn = _stats_sum(
                a_base, p_base, n_base, c_start, c_end, C, eps, mode, BLOCK_C, ACC64
            )
    if mode == 3:
        p_ap = tl.max(acc_ap, 0, keep_dims=True)
        p_an = tl.max(acc_an, 0, keep_dims=True)
        p_pn = tl.max(acc_pn, 0, keep_dims=True)
    elif mode == 4:
        p_ap = tl.min(acc_ap, 0, keep_dims=True)
        p_an = tl.min(acc_an, 0, keep_dims=True)
        p_pn = tl.min(acc_pn, 0, keep_dims=True)
    else:
        p_ap = tl.sum(acc_ap, 0, keep_dims=True)
        p_an = tl.sum(acc_an, 0, keep_dims=True)
        p_pn = tl.sum(acc_pn, 0, keep_dims=True)
    return p_ap, p_an, p_pn


@triton.jit
def _finish(part, mode, pp, ACC64: tl.constexpr):
    """Turn an accumulated norm sum / extremum into the Lp distance."""
    if mode == 2:
        d = tl.sqrt(part)
    elif mode == 5:
        if ACC64:
            d = part
        else:
            d = tl.exp2((1.0 / pp) * tl.log2(part))
    else:
        d = part
    return d


@triton.jit(do_not_specialize=_ROWS_NOS)
def _tm_rows_kernel(
    a_ptr,
    p_ptr,
    n_ptr,
    o_ptr,
    R,
    C,
    margin,
    eps,
    pp,
    scale,
    RPP,
    mode,
    swap,
    g0s,
    g1s,
    g2s,
    g3s,
    g0a,
    g1a,
    g2a,
    g3a,
    g0p,
    g1p,
    g2p,
    g3p,
    g0n,
    g1n,
    g2n,
    g3n,
    WRITE_ROWS: tl.constexpr,
    FINAL: tl.constexpr,
    BLOCK_C: tl.constexpr,
    ACC64: tl.constexpr,
):
    pid = tl.program_id(0)
    r0 = pid * RPP
    one = tl.arange(0, 1)
    lsum = _new_one(ACC64)
    dt = o_ptr.dtype.element_ty
    for i in range(0, RPP):
        r = r0 + i
        if r < R:
            rem = r
            off_a = 0
            off_p = 0
            off_n = 0

            idx = rem % g0s
            rem = rem // g0s
            off_a += idx * g0a
            off_p += idx * g0p
            off_n += idx * g0n
            idx = rem % g1s
            rem = rem // g1s
            off_a += idx * g1a
            off_p += idx * g1p
            off_n += idx * g1n
            idx = rem % g2s
            rem = rem // g2s
            off_a += idx * g2a
            off_p += idx * g2p
            off_n += idx * g2n
            idx = rem % g3s
            rem = rem // g3s
            off_a += idx * g3a
            off_p += idx * g3p
            off_n += idx * g3n

            p_ap, p_an, p_pn = _row_parts(
                a_ptr + off_a,
                p_ptr + off_p,
                n_ptr + off_n,
                0,
                C,
                C,
                eps,
                mode=mode,
                pp=pp,
                BLOCK_C=BLOCK_C,
                ACC64=ACC64,
            )
            d_ap = _finish(p_ap, mode, pp, ACC64)
            d_an = _finish(p_an, mode, pp, ACC64)
            d_pn = _finish(p_pn, mode, pp, ACC64)
            d_an = tl.where(swap != 0, tl.minimum(d_an, d_pn), d_an)
            loss = tl.maximum(margin + d_ap - d_an, 0.0)
            lsum += loss
            if WRITE_ROWS:
                tl.store(o_ptr + r + one, loss.to(dt))
    if not WRITE_ROWS:
        if FINAL:
            tl.store(o_ptr + one, (lsum * scale).to(dt))
        else:
            tl.store(o_ptr + pid + one, lsum)


@triton.jit(do_not_specialize=_COLS_NOS)
def _tm_cols_kernel(
    a_ptr,
    p_ptr,
    n_ptr,
    ap_ptr,
    an_ptr,
    pn_ptr,
    R,
    C,
    eps,
    pp,
    chunk,
    Gc,
    mode,
    g0s,
    g1s,
    g2s,
    g3s,
    g0a,
    g1a,
    g2a,
    g3a,
    g0p,
    g1p,
    g2p,
    g3p,
    g0n,
    g1n,
    g2n,
    g3n,
    BLOCK_C: tl.constexpr,
    ACC64: tl.constexpr,
):
    pid = tl.program_id(0)
    one = tl.arange(0, 1)
    c_start = pid * chunk
    c_end = tl.minimum(c_start + chunk, C)
    for r in range(0, R):
        rem = r
        off_a = 0
        off_p = 0
        off_n = 0

        idx = rem % g0s
        rem = rem // g0s
        off_a += idx * g0a
        off_p += idx * g0p
        off_n += idx * g0n
        idx = rem % g1s
        rem = rem // g1s
        off_a += idx * g1a
        off_p += idx * g1p
        off_n += idx * g1n
        idx = rem % g2s
        rem = rem // g2s
        off_a += idx * g2a
        off_p += idx * g2p
        off_n += idx * g2n
        idx = rem % g3s
        rem = rem // g3s
        off_a += idx * g3a
        off_p += idx * g3p
        off_n += idx * g3n

        p_ap, p_an, p_pn = _row_parts(
            a_ptr + off_a,
            p_ptr + off_p,
            n_ptr + off_n,
            c_start,
            c_end,
            C,
            eps,
            mode,
            pp,
            BLOCK_C=BLOCK_C,
            ACC64=ACC64,
        )
        pos = r * Gc + pid
        tl.store(ap_ptr + pos + one, p_ap)
        tl.store(an_ptr + pos + one, p_an)
        tl.store(pn_ptr + pos + one, p_pn)


@triton.jit(do_not_specialize=_COMB_NOS)
def _tm_combine_kernel(
    ap_ptr,
    an_ptr,
    pn_ptr,
    o_ptr,
    R,
    Gc,
    margin,
    pp,
    scale,
    mode,
    swap,
    WRITE_ROWS: tl.constexpr,
    BG: tl.constexpr,
    ACC64: tl.constexpr,
):
    kk = tl.arange(0, BG)
    mk = kk < Gc
    one = tl.arange(0, 1)
    lsum = _new_one(ACC64)
    dt = o_ptr.dtype.element_ty
    for r in range(0, R):
        base = r * Gc
        ap = tl.load(ap_ptr + base + kk, mask=mk, other=0.0)
        an = tl.load(an_ptr + base + kk, mask=mk, other=0.0)
        pn = tl.load(pn_ptr + base + kk, mask=mk, other=0.0)
        if mode == 4:
            s_ap = tl.min(tl.where(mk, ap, float("inf")), 0, keep_dims=True)
            s_an = tl.min(tl.where(mk, an, float("inf")), 0, keep_dims=True)
            s_pn = tl.min(tl.where(mk, pn, float("inf")), 0, keep_dims=True)
        elif mode == 3:
            s_ap = tl.max(ap, 0, keep_dims=True)
            s_an = tl.max(an, 0, keep_dims=True)
            s_pn = tl.max(pn, 0, keep_dims=True)
        else:
            s_ap = tl.sum(ap, 0, keep_dims=True)
            s_an = tl.sum(an, 0, keep_dims=True)
            s_pn = tl.sum(pn, 0, keep_dims=True)
        d_ap = _finish(s_ap, mode, pp, ACC64)
        d_an = _finish(s_an, mode, pp, ACC64)
        d_pn = _finish(s_pn, mode, pp, ACC64)
        d_an = tl.where(swap != 0, tl.minimum(d_an, d_pn), d_an)
        loss = tl.maximum(margin + d_ap - d_an, 0.0)
        lsum += loss
        if WRITE_ROWS:
            tl.store(o_ptr + r + one, loss.to(dt))
    if not WRITE_ROWS:
        tl.store(o_ptr + one, (lsum * scale).to(dt))


@triton.jit(do_not_specialize=_RED_NOS)
def _tm_reduce_kernel(
    i_ptr,
    o_ptr,
    n,
    scale,
    BLOCK_N: tl.constexpr,
    ACC64: tl.constexpr,
):
    if ACC64:
        acc = tl.zeros([BLOCK_N], tl.float64)
    else:
        acc = tl.zeros([BLOCK_N], tl.float32)
    cols = tl.arange(0, BLOCK_N)
    for i0 in range(0, n, BLOCK_N):
        ii = i0 + cols
        acc += tl.load(i_ptr + ii, mask=ii < n, other=0.0).to(acc.dtype)
    s = tl.sum(acc, 0, keep_dims=True)
    tl.store(o_ptr + tl.arange(0, 1), (s * scale).to(o_ptr.dtype.element_ty))


def _lead_groups(tensors, shape):
    """Collapse the non-reduced dims into groups with a uniform stride."""
    nd = len(shape) - 1
    if nd <= 0:
        return []
    groups = []
    cur_size = shape[nd - 1]
    cur_strides = [t.stride(nd - 1) for t in tensors]
    for i in range(nd - 2, -1, -1):
        if all(t.stride(i) == cur_strides[j] * cur_size for j, t in enumerate(tensors)):
            cur_size *= shape[i]
        else:
            groups.append((cur_size, cur_strides))
            cur_size = shape[i]
            cur_strides = [t.stride(i) for t in tensors]
    groups.append((cur_size, cur_strides))
    return groups


def _mode_of(pval):
    if pval == 2.0:
        return 2
    if pval == 1.0:
        return 1
    if pval == 0.0:
        return 0
    if pval == float("inf"):
        return 3
    if pval == float("-inf"):
        return 4
    return 5


def triplet_margin_loss(
    anchor,
    positive,
    negative,
    margin=1.0,
    p=2.0,
    eps=1e-6,
    swap=False,
    reduction="mean",
):
    logger.debug("GEMS TRIPLET_MARGIN_LOSS")

    if isinstance(reduction, str):
        red = {"none": 0, "mean": 1, "sum": 2}[reduction.lower()]
    elif reduction is None:
        red = 0
    else:
        red = int(reduction)
    if red not in (0, 1, 2):
        raise ValueError("triplet_margin_loss: invalid reduction")

    shape = torch.broadcast_shapes(
        tuple(anchor.shape), tuple(positive.shape), tuple(negative.shape)
    )
    out_dtype = torch.promote_types(
        torch.promote_types(anchor.dtype, positive.dtype), negative.dtype
    )
    a = anchor if tuple(anchor.shape) == shape else anchor.expand(shape)
    b = positive if tuple(positive.shape) == shape else positive.expand(shape)
    c = negative if tuple(negative.shape) == shape else negative.expand(shape)
    dev = anchor.device
    # The Triton backend cannot take float64 pointer arguments (kernel
    # compilation fails), so float64 inputs are computed in float32 and the
    # result is widened back to the promoted dtype.
    res_dtype = out_dtype
    if out_dtype == torch.float64:
        a = a.to(torch.float32)
        b = b.to(torch.float32)
        c = c.to(torch.float32)
        out_dtype = torch.float32
    acc64 = out_dtype == torch.float64
    acc_dtype = torch.float64 if acc64 else torch.float32

    ndim = len(shape)
    if ndim == 0:
        C = 1
        R = 1
        out_shape = ()
    else:
        C = shape[-1]
        R = 1
        for s in shape[:-1]:
            R *= s
        out_shape = tuple(shape[:-1])

    pval = float(p)
    mode = _mode_of(pval)
    swap_i = 1 if swap else 0
    scale = (1.0 / R) if red == 1 else 1.0
    if acc64 and mode not in (0, 1, 2):
        raise ValueError("triplet_margin_loss: fp64 only supports p in {0,1,2}")

    if red == 0:
        out = torch.empty(out_shape, dtype=out_dtype, device=dev)
        rows = out.reshape(-1)
    else:
        out = torch.empty((), dtype=out_dtype, device=dev)
        rows = None

    def _ret(t):
        return t.to(res_dtype) if res_dtype != out_dtype else t

    if R <= 0:
        return _ret(out)

    groups = _lead_groups([a, b, c], shape) if ndim >= 1 else []
    if len(groups) > _MAX_LEAD:
        raise RuntimeError(
            "triplet_margin_loss: unsupported stride pattern "
            f"({len(groups)} leading stride groups)"
        )
    gs = [1] * _MAX_LEAD
    ga = [0] * _MAX_LEAD
    gp = [0] * _MAX_LEAD
    gn = [0] * _MAX_LEAD
    for k, (size, strides) in enumerate(groups):
        gs[k] = int(size)
        ga[k] = int(strides[0])
        gp[k] = int(strides[1])
        gn[k] = int(strides[2])
    gargs = [
        gs[0],
        gs[1],
        gs[2],
        gs[3],
        ga[0],
        ga[1],
        ga[2],
        ga[3],
        gp[0],
        gp[1],
        gp[2],
        gp[3],
        gn[0],
        gn[1],
        gn[2],
        gn[3],
    ]

    block_c = 4096 if C >= 65536 else 1024
    total = R * C

    if total <= 65536 and R <= 256:
        # Whole problem fits one program: single launch, no temporaries.
        _tm_rows_kernel[(1,)](
            a,
            b,
            c,
            rows if red == 0 else out,
            R,
            C,
            float(margin),
            float(eps),
            pval,
            scale,
            R,
            mode,
            swap_i,
            *gargs,
            WRITE_ROWS=(red == 0),
            FINAL=(red != 0),
            BLOCK_C=block_c,
            ACC64=acc64,
            num_warps=1,
        )
        return _ret(out)

    if R < 128:
        # Few rows, potentially very many columns: split the reduction axis.
        want = -(-C // 2048)
        chunk = block_c
        if want > chunk:
            chunk = ((want + block_c - 1) // block_c) * block_c
        Gc = -(-C // chunk)
        part_ap = torch.empty((R, Gc), dtype=acc_dtype, device=dev)
        part_an = torch.empty((R, Gc), dtype=acc_dtype, device=dev)
        part_pn = torch.empty((R, Gc), dtype=acc_dtype, device=dev)
        _tm_cols_kernel[(Gc,)](
            a,
            b,
            c,
            part_ap,
            part_an,
            part_pn,
            R,
            C,
            float(eps),
            pval,
            chunk,
            Gc,
            mode,
            *gargs,
            BLOCK_C=block_c,
            ACC64=acc64,
            num_warps=1,
        )
        _tm_combine_kernel[(1,)](
            part_ap,
            part_an,
            part_pn,
            rows if red == 0 else out,
            R,
            Gc,
            float(margin),
            pval,
            scale,
            mode,
            swap_i,
            WRITE_ROWS=(red == 0),
            BG=_COMB_BLOCK,
            ACC64=acc64,
            num_warps=1,
        )
        return _ret(out)

    # Many rows: one program per row group, then a tiny final reduction.
    rpp = -(-R // 2048)
    G = -(-R // rpp)
    if red == 0:
        _tm_rows_kernel[(G,)](
            a,
            b,
            c,
            rows,
            R,
            C,
            float(margin),
            float(eps),
            pval,
            scale,
            rpp,
            mode,
            swap_i,
            *gargs,
            WRITE_ROWS=True,
            FINAL=False,
            BLOCK_C=block_c,
            ACC64=acc64,
            num_warps=1,
        )
        return _ret(out)

    parts = torch.empty((G,), dtype=acc_dtype, device=dev)
    _tm_rows_kernel[(G,)](
        a,
        b,
        c,
        parts,
        R,
        C,
        float(margin),
        float(eps),
        pval,
        scale,
        rpp,
        mode,
        swap_i,
        *gargs,
        WRITE_ROWS=False,
        FINAL=False,
        BLOCK_C=block_c,
        ACC64=acc64,
        num_warps=1,
    )
    _tm_reduce_kernel[(1,)](
        parts,
        out,
        G,
        scale,
        BLOCK_N=_RED_BLOCK,
        ACC64=acc64,
        num_warps=1,
    )
    return _ret(out)
